-- Initial file generated by Claude Sonnet 5.5

module Zocalo.Gallery.ZipMakerSpec(tests) where

import Codec.Archive.Zip(Archive, filesInArchive, findEntryByPath, fromEntry, toArchive)

import Data.NanoID(NanoID(NanoID))
import Data.Time.Clock.POSIX(posixSecondsToUTCTime)

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit(assertBool, (@?=))

import qualified Data.ByteString      as BS
import qualified Data.ByteString.Lazy as LBS
import qualified Data.List            as List

import Zocalo.Gallery.Entity.Savable(
    CommentSavable(CommentSavable)
  , GallerySavable(GallerySavable)
  , SubmissionSavable(SubmissionSavable)
  , SubmissionStatus(Public, Waiting)
  )

import Zocalo.Gallery.ZipMaker(galleryToZIP)


-- The 8-byte PNG signature, base64-encoded; a valid base64 payload is all the exporter looks at
pngBase64 :: Text
pngBase64 = "iVBORw0KGgo="

submission :: Text -> Text -> SubmissionStatus -> SubmissionSavable
submission uploader image status =
  SubmissionSavable uploader image (posixSecondsToUTCTime 0) status (Just "{\"description\":\"my cool robot\"}")
                    "<project/>" [CommentSavable "nice!" "Bo" (posixSecondsToUTCTime 0)]

gallery :: Maybe Text -> [SubmissionSavable] -> GallerySavable
gallery starter subs =
  GallerySavable "Period 3" "netsblox" (NanoID "V1StGXR8_Z5jdHi6B-myT") "Ms. Frizzle" (posixSecondsToUTCTime 0)
                 (Just "A description") starter subs

exported :: GallerySavable -> (ByteString, Archive)
exported g = (name, toArchive bytes)
  where
    (name, bytes) = galleryToZIP 1700000000 g

contents :: FilePath -> Archive -> Maybe ByteString
contents path archive = fmap (\entry -> LBS.toStrict $ fromEntry entry) $ findEntryByPath path archive

tests :: Test
tests =
  testGroup "Zocalo.Gallery.ZipMaker.galleryToZIP"
    [ testCase "names the file after the gallery, template, and ID" $ do
        let (name, _) = exported $ gallery Nothing []
        -- TODO: If this fails showing text like "NanoID {unNanoID = ...", the Show instance leaks into the filename.
        assertBool (show name) ("zocalo===Period 3===netsblox===" `BS.isPrefixOf` name)
        assertBool (show name) ("V1StGXR8_Z5jdHi6B-myT" `BS.isInfixOf` name)

    , testCase "always contains info.txt, with the teacher and description" $ do
        let (_, archive) = exported $ gallery Nothing []
        case contents "info.txt" archive of
          Nothing   -> assertBool "info.txt is missing" False
          Just info -> do
            assertBool (show info) ("\"teacher\":\"Ms. Frizzle\"" `BS.isInfixOf` info)
            assertBool (show info) ("\"description\":\"A description\"" `BS.isInfixOf` info)

    , testCase "includes a starter file with the template's extension only when a starter exists" $ do
        let (_, withStarter)    = exported $ gallery (Just "<starter/>") []
        let (_, withoutStarter) = exported $ gallery Nothing []
        contents "starter.xml" withStarter @?= Just "<starter/>"
        List.filter (List.isPrefixOf "starter.") (filesInArchive withoutStarter) @?= []

    , testCase "lays out each upload as uploads/<n>_<name>/{info.json,data.xml,image.png}" $ do
        let (_, archive) = exported $ gallery Nothing [submission "Ana" pngBase64 Public]
        let paths        = filesInArchive archive
        mapM_'' (\p -> assertBool (p <> " is missing") (p `elem` paths))
                ["uploads/1_Ana/info.json", "uploads/1_Ana/data.xml", "uploads/1_Ana/image.png"]
        contents "uploads/1_Ana/data.xml" archive @?= Just "<project/>"

    , testCase "records each upload's status and comments in its info.json" $ do
        let (_, archive) = exported $ gallery Nothing [submission "Ana" pngBase64 Waiting]
        case contents "uploads/1_Ana/info.json" archive of
          Nothing   -> assertBool "info.json is missing" False
          Just info -> do
            assertBool (show info) ("\"status\":\"waiting\""       `BS.isInfixOf` info)
            assertBool (show info) ("\"description\":\"my cool robot\"" `BS.isInfixOf` info)
            assertBool (show info) ("\"comment\":\"nice!\""        `BS.isInfixOf` info)

    , testCase "gives same-named uploaders separate folders" $ do
        let (_, archive) = exported $ gallery Nothing [submission "Ana" pngBase64 Public, submission "Ana" pngBase64 Public]
        let paths        = filesInArchive archive
        assertBool "uploads/1_Ana/ missing" ("uploads/1_Ana/info.json" `elem` paths)
        assertBool "uploads/2_Ana/ missing" ("uploads/2_Ana/info.json" `elem` paths)

    , testCase "cannot be tricked into writing outside uploads/ by a hostile uploader name" $ do
        let (_, archive) = exported $ gallery Nothing [submission "../../etc/passwd" pngBase64 Public]
        let uploads      = List.filter (\p -> not ("info.txt" == p)) $ filesInArchive archive
        assertBool (show uploads) (not $ List.null uploads)
        mapM_'' (\p -> assertBool p ("uploads/" `List.isPrefixOf` p && not (".." `List.isInfixOf` p))) uploads

    , testCase "omits the image file when the stored image is not valid base64 (e.g., SVG text)" $ do
        let (_, archive) = exported $ gallery Nothing [submission "Ana" "<svg xmlns='http://www.w3.org/2000/svg'/>" Public]
        assertBool "no image entry expected" (not $ "uploads/1_Ana/image.png" `elem` filesInArchive archive)
    ]
  where
    mapM_'' f xs = traverse f xs >> return ()
